# aplicar-dashboard-alertas-franquicias.ps1
#
# Aplica, en tu clon local de fpt-contratos, los cambios del dashboard de
# Franquicias (categorias activas/por-abrir/falta-de-abrir, clicables), la
# nueva pagina de Alertas, y el nuevo panel de administracion de
# destinatarios de avisos (quien recibe cada tipo de correo automatico).
#
# Como correrlo:
#   1. Abre PowerShell en la carpeta raiz de tu clon de fpt-contratos
#      (donde estan las carpetas backend/ y frontend/).
#   2. .\aplicar-dashboard-alertas-franquicias.ps1
#   3. Revisa 'git status' / 'git diff' si quieres ver el detalle antes del
#      commit (el script hace commit y push automaticamente al final).
#
# Despues de correrlo, falta un paso en el servidor (Render / base de datos):
#   - Aplicar la nueva migracion una vez: desde backend/, con DATABASE_URL
#     apuntando a la base de produccion, correr:
#       npm run migrate:franquicia-alertas
#   - Redesplegar el backend en Render para que tome el codigo nuevo (si no
#     tienes auto-deploy en push, hazlo a mano desde el dashboard de Render).

$ErrorActionPreference = "Stop"

function Write-FileFromBase64($relPath, $b64) {
    $full = Join-Path (Get-Location) $relPath
    $dir = Split-Path $full -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "Escrito: $relPath"
}

if (-not (Test-Path ".git")) {
    Write-Host "No encuentro una carpeta .git aqui. Corre este script desde la raiz de tu clon de fpt-contratos." -ForegroundColor Red
    exit 1
}

